function setup({ listId, email, initialName, updatedName }) {
  if (
    typeof listId !== "string" ||
    !/^\d+$/.test(listId) ||
    !Number.isSafeInteger(Number(listId)) ||
    Number(listId) < 1
  )
    throw Error("Enter a numeric list ID");
  if (typeof email !== "string" || !/^\S+@\S+\.\S+$/.test(email.trim()))
    throw Error("Enter a valid email");
  if (
    typeof initialName !== "string" ||
    !initialName.trim() ||
    typeof updatedName !== "string" ||
    !updatedName.trim()
  )
    throw Error("Enter both names");
  return {
    listId: Number(listId),
    email: email.trim(),
    initialName: initialName.trim(),
    updatedName: updatedName.trim(),
    url: "https://api.egoiapp.com/lists/" + listId + "/contacts",
    body: { base: { email: email.trim(), first_name: initialName.trim() }, extra: [] },
    update: { base: { first_name: updatedName.trim() }, extra: [] },
  };
}

return [{ json: setup({ listId: "", email: "", initialName: "", updatedName: "" }) }];

const c = $input.first().json;
if (!c || typeof c.contact_id !== "string" || !/^[a-f0-9]{10}$/i.test(c.contact_id))
  throw Error("Contact ID missing or invalid");
return $input.all();

function confirm({ body, contactId, email, updatedName }) {
  const c = body?.base;
  if (
    !c ||
    c.contact_id !== contactId ||
    typeof c.email !== "string" ||
    c.email.toLowerCase() !== email.toLowerCase() ||
    c.first_name !== updatedName
  )
    throw Error("Returned contact does not match");
  return { contact: body };
}

const input = $("Set contact details").first().json,
  c = $("Confirm created contact").first().json;
return [
  {
    json: confirm({
      body: $input.first().json,
      contactId: c.contact_id,
      email: input.email,
      updatedName: input.updatedName,
    }).contact,
  },
];
